//! 部分原行MIPで主解だけを探す診断。部分モデルの下界/状態を元問題へ移さない。
use mip_codex::{mps,model::Model,solve::{self,Limits}};
use std::{collections::HashSet,time::{Instant,Duration}};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|s|s=="build-info"){println!("{}",serde_json::json!({"source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let v:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[2]).unwrap()).unwrap();let sources:Vec<usize>=if v.get("indices").is_some(){serde_json::from_value(v["indices"].clone()).unwrap()}else{serde_json::from_value::<Vec<(usize,f64)>>(v["row_sources"].clone()).unwrap().into_iter().map(|(i,_)|i).collect()};let mut active=HashSet::new();let mut indices=vec![];for i in sources{assert!(i<m.rows.len());if active.insert(i){indices.push(i);}}let seconds:f64=a[3].parse().unwrap();let start=Instant::now();let deadline=start+Duration::from_secs_f64(seconds);let mut empty=0usize;
 for round in 0..128{if Instant::now()>=deadline{break;}let mut subset=Model{name:m.name.clone(),maximize:m.maximize,offset:m.offset,offset_enclosure:m.offset_enclosure,original_decimal:m.original_decimal,variables:m.variables.clone(),rows:indices.iter().map(|&i|m.rows[i].clone()).collect()};if a.get(4).is_some_and(|s|s=="1"){for v in &mut subset.variables{v.objective=0.;v.objective_enclosure=Some([0.;2]);}subset.offset=0.;subset.offset_enclosure=Some([0.;2]);}let slice=(0.25*2f64.powi(empty.min(4)as i32)).min(deadline.saturating_duration_since(Instant::now()).as_secs_f64());if slice<=0.{break;}let limits=Limits{seconds:slice,nodes:4096,row_generation:false,row_generation_report:false,lp_dual_root:false,primal_probe:false,primal_repair:false,box_primal:false,lp_diving:false,objective_lp_dive:false,feasibility_pump:false,rins:false,terminal_neighborhood:false,binary_graph:false,cover_cuts:false,mir_cuts:false,gomory_cuts:false,aggregate_cuts:false,clique_cuts:false,three_row_cuts:false,rounding_cuts:false,objective_rounding:false,objective_rounding_all:false,objective_box_report:false,objective_domain_report:false,zero_dominance:false,..Limits::default()};let r=solve::solve(&subset,&limits);println!("{}",serde_json::json!({"stage":"subset","round":round,"active":indices.len(),"status":r.status,"objective":r.objective,"nodes":r.nodes,"lp_solves":r.lp_solves,"slice":slice,"seconds":start.elapsed().as_secs_f64(),"claim":"subset status only"}));
  if let Some(values)=r.values{let point:Vec<_>=m.variables.iter().map(|v|values[&v.name]).collect();if point.iter().all(|v|v.is_finite())&&m.check(&point,true,1e-7).is_ok()&&m.objective(&point).is_finite(){println!("{}",serde_json::json!({"stage":"original_candidate","objective":m.objective(&point),"values":values,"seconds":start.elapsed().as_secs_f64(),"claim":"original checked primal candidate; not an optimality claim"}));break;}empty=0;let mut violated=vec![];
   for(i,row)in m.rows.iter().enumerate(){if i%4096==0&&Instant::now()>=deadline{break;}if active.contains(&i){continue;}let x:f64=row.coefficients.iter().map(|&(j,c)|c*point[j]).sum();let d=row.lower.map_or(0.,|b|(b-x).max(0.)).max(row.upper.map_or(0.,|b|(x-b).max(0.)));if d>1e-7{let scale=row.coefficients.iter().map(|&(_,a)|a.abs()).sum::<f64>().max(1.);violated.push((i,d/scale));}}
   violated.sort_by(|a,b|b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));let added=violated.len().min(512);println!("{}",serde_json::json!({"stage":"separate_integer_candidate","violated":violated.len(),"added":added,"round":round}));if added==0{break;}for(i,_)in violated.into_iter().take(512){assert!(active.insert(i));indices.push(i);}
  }else{empty+=1;if r.status=="infeasible"{break;}}
 }println!("{}",serde_json::json!({"stage":"exit","active":indices.len(),"seconds":start.elapsed().as_secs_f64()}));}
